import { BOOK_CONSULTATION_PATH, buildBookConsultationPath } from '../../lib/serviceFlow'

const GALLERY_VIEWPORT_HEIGHT_CLASS =
  'h-[min(52vh,20rem)] md:h-[clamp(26.25rem,calc(100vh-8.25rem),58.375rem)]'

// Cap side thumbnails to main image height; extra images scroll inside the column.
const SIDE_IMAGES_SCROLL_CLASS =
  'h-[min(52vh,20rem)] max-h-[min(52vh,20rem)] min-h-0 md:h-[clamp(26.25rem,calc(100vh-8.25rem),58.375rem)] md:max-h-[clamp(26.25rem,calc(100vh-8.25rem),58.375rem)]'

const SIDE_THUMB_BUTTON_CLASS =
  'shrink-0 overflow-hidden rounded-[12px] transition-opacity h-[clamp(3.75rem,11vw,4.5rem)] w-full md:h-[clamp(5.125rem,6.5vw,6.4375rem)] md:w-[clamp(4rem,5vw,5rem)]'

function PackageImageLightbox({ open, image, title, onClose }) {
  useEffect(() => {
    if (!open) return undefined

    const handleKeyDown = event => {
      if (event.key === 'Escape') onClose?.()
    }

    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    window.addEventListener('keydown', handleKeyDown)

    return () => {
      document.body.style.overflow = previousOverflow
      window.removeEventListener('keydown', handleKeyDown)
    }
  }, [open, onClose])

  if (!open || !image) return null

  return (
    <div
      className="fixed inset-0 z-[200] flex items-center justify-center bg-black/85 p-4"
      role="dialog"
      aria-modal="true"
      aria-label={`${title} image preview`}
      onClick={onClose}
    >
      <button
        type="button"
        onClick={onClose}
        className="absolute right-4 top-4 z-10 flex h-10 w-10 items-center justify-center rounded-full bg-white/15 text-2xl leading-none text-white"
        aria-label="Close image preview"
      >
        ×
      </button>
      <div
        className="relative max-h-[90vh] max-w-full overflow-hidden"
        onClick={event => event.stopPropagation()}
        onKeyDown={() => {}}
        role="presentation"
      >
        {/* Scale from top-left so bottom-right Gemini watermark is clipped */}
        <AppImage
          src={image}
          alt={title}
          eager
          className="block max-h-[90vh] max-w-full origin-top-left object-contain scale-[1.14]"
        />
      </div>
    </div>
  )
}

function ConsultationLinkButton({ label, className = '', consultationPath = BOOK_CONSULTATION_PATH }) {
  return (
    <Link
      to={consultationPath}
      className={`group flex w-full items-center justify-between rounded-full bg-[#D4BA8E] pl-6 pr-1.5 py-1.5 text-[13px] font-medium text-white transition-colors hover:bg-[#C6AB7F] ${className}`}
    >
      <span className="mr-5">{label}</span>
      <span className="flex h-9 w-9 items-center justify-center rounded-full bg-white text-[#D4BA8E] shadow-sm">
        <svg
          className="h-[20px] w-[20px] transition-transform duration-300 ease-out group-hover:rotate-45"
          viewBox="0 0 20 20"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M5.82812 5.83398H14.1615M14.1615 5.83398V14.1673M14.1615 5.83398L5.82812 14.1673"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </span>
    </Link>
  )
}

function QuantityControl({ quantity, onDecrement, onIncrement }) {
  return (
    <div className="mt-6 flex items-center gap-2">
      <p className="text-[12px] font-medium text-[#591902]">Quantity :</p>

      <div className="flex items-center border border-[#D9D9D9] bg-white">
        {/* Minus */}
        <button
          type="button"
          onClick={onDecrement}
          className="flex h-[28px] w-[28px] items-center justify-center border-r border-[#D9D9D9] text-[18px] font-light text-black"
        >
          −
        </button>

        {/* Quantity */}
        <div className="flex h-[28px] w-[28px] items-center justify-center text-[16px] font-medium text-black">
          {quantity}
        </div>

        {/* Plus */}
        <button
          type="button"
          onClick={onIncrement}
          className="flex h-[28px] w-[28px] items-center justify-center border-l border-[#D9D9D9] text-[18px] font-light text-black"
        >
          +
        </button>
      </div>
    </div>
  )
}
function AccordionSection({ title, body, defaultOpen = false }) {
  const [isOpen, setIsOpen] = useState(defaultOpen)

  return (
    <div className="border-t border-[#E5E0D8] py-4">
      <button
        type="button"
        onClick={() => setIsOpen(open => !open)}
        className="flex w-full items-center justify-between gap-4 text-left outline-none focus:outline-none focus-visible:outline-none"
      >
        <span className="text-[15px] leading-none text-[#6B7152] font-semibold">{title}</span>
        <span
          className="text-[22px] leading-none text-[#C4A36B] transition-transform duration-300 ease-out"
          style={{ transform: isOpen ? 'rotate(45deg)' : 'rotate(0deg)' }}
        >
          +
        </span>
      </button>

      <div
        className="grid transition-[grid-template-rows,opacity] duration-500 ease-[cubic-bezier(0.32,0,0.15,1)]"
        style={{
          gridTemplateRows: isOpen ? '1fr' : '0fr',
          opacity: isOpen ? 1 : 0.55,
        }}
      >
        <div className="overflow-hidden">
          <p className="mt-3 whitespace-pre-line text-[13px] leading-[1.65] text-[#591902] opacity-60">
            {body}
          </p>
        </div>
      </div>
    </div>
  )
}

