const TRUST_ITEMS = [
  { label: 'Trusted Vendors', Icon: VendorIcon },
  { label: 'Clear Pricing', Icon: PricingIcon },
  { label: 'Easy Support', Icon: SupportIcon },
  { label: 'On-Time Setup', Icon: ClockIcon },
  { label: 'Real Flowers', Icon: FlowerIcon },
]

export default function SingleProductPageContent({
  title,
  price,
  originalPrice = '',
  discountBadge = '',
  intro,
  customDetailsContent = null,
  beforePriceContent = null,
  customPriceContent = null,
  customContent = null,
  accordionSections = [],
  mainImage,
  sideImages = [],
  imageMetaByUrl = {},
  quantity = 1,
  onDecrement,
  onIncrement,
  promptContent,
  addToCartLabel = 'Add to cart',
  addToCartMessage = '',
  relatedProducts = [],
  disableAddToCart = false,
  isAddingToCart = false,
  onAddToCart,
  ctaButtonText = 'Book a Consultation',
  testimonials = [],
  hideHeaderPrice = false,
  consultationOnly = false,
  consultationPackage = null,
}) {
  const desktopSectionTop = '58px'
  const addToCartDisabled = disableAddToCart || isAddingToCart
  const addToCartButtonLabel = isAddingToCart ? 'Adding...' : addToCartLabel
  const hidePrice = hideHeaderPrice || consultationOnly
  const consultationPath = buildBookConsultationPath({
    packageId: consultationPackage?.id ?? consultationPackage?.packageId,
    packageTitle: consultationPackage?.title ?? consultationPackage?.packageTitle,
    packageSlug: consultationPackage?.slug ?? consultationPackage?.packageSlug,
    source: consultationPackage?.source ?? (consultationOnly ? 'corporate-decor' : undefined),
  })

  return (
    <ProductImageLayout
      title={title}
      price={price}
      originalPrice={originalPrice}
      discountBadge={discountBadge}
      intro={intro}
      customDetailsContent={customDetailsContent}
      beforePriceContent={beforePriceContent}
      customPriceContent={customPriceContent}
      customContent={customContent}
      accordionSections={accordionSections}
      mainImage={mainImage}
      sideImages={sideImages}
      imageMetaByUrl={imageMetaByUrl}
      quantity={quantity}
      onDecrement={onDecrement}
      onIncrement={onIncrement}
      promptContent={promptContent}
      addToCartDisabled={addToCartDisabled}
      addToCartButtonLabel={addToCartButtonLabel}
      addToCartMessage={addToCartMessage}
      relatedProducts={relatedProducts}
      onAddToCart={onAddToCart}
      ctaButtonText={ctaButtonText}
      testimonials={testimonials}
      desktopSectionTop={desktopSectionTop}
      hideHeaderPrice={hidePrice}
      consultationOnly={consultationOnly}
      consultationPath={consultationPath}
    />
  )
}

function RelatedProductsCarousel({ products, hidePrice = false }) {
  const CARDS_PER_VIEW = 3
  const [page, setPage] = useState(0)
  const totalPages = Math.max(1, Math.ceil(products.length / CARDS_PER_VIEW))
  const visibleProducts = useMemo(
    () =>
      assignDistinctCoverIndices(
        products.slice(page * CARDS_PER_VIEW, page * CARDS_PER_VIEW + CARDS_PER_VIEW),
        { columns: 3 }
      ),
    [page, products]
  )

  return (
    <div className="relative mt-4 lg:mt-8 overflow-hidden">
      <div className="px-[20px] sm:px-[50px] lg:px-[100px]">
        <p
          className="text-[22px] md:text-[32px] font-semibold text-[#2D2D2D]"
          style={{ fontFamily: "'Malgin', serif" }}
        >
          You May Also Like
        </p>

        <div className="mt-4 grid grid-cols-1 gap-4 sm:grid-cols-2 md:grid-cols-3">
          {visibleProducts.map(product => (
            <PackageCard key={product.id ?? product.title} pkg={product} hidePrice={hidePrice} />
          ))}
        </div>
      </div>

      {totalPages > 1 && (
        <>
          <button
            type="button"
            onClick={() => setPage(p => p - 1)}
            disabled={page === 0}
            className="absolute left-0 top-1/2 z-10 -translate-y-1/2 flex h-[clamp(3.5rem,6vw,5rem)] w-[clamp(1.75rem,3vw,2.5rem)] items-center justify-center rounded-r-full bg-[#E7E0DA] text-[#2D2D2D] disabled:opacity-30 disabled:cursor-not-allowed"
            aria-label="Previous"
          >
            <svg
              className="h-6 w-6"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M19 12H5M5 12L12 19M5 12L12 5" />
            </svg>
          </button>

          <button
            type="button"
            onClick={() => setPage(p => p + 1)}
            disabled={page >= totalPages - 1}
            className="absolute right-0 top-1/2 z-10 -translate-y-1/2 flex h-[clamp(3.5rem,6vw,5rem)] w-[clamp(1.75rem,3vw,2.5rem)] items-center justify-center rounded-l-full bg-[#E7E0DA] text-[#2D2D2D] disabled:opacity-30 disabled:cursor-not-allowed"
            aria-label="Next"
          >
            <svg
              className="h-6 w-6"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M5 12H19M19 12L12 19M19 12L12 5" />
            </svg>
          </button>

          <div className="mt-6 flex items-center justify-center gap-1.5">
            {Array.from({ length: totalPages }, (_, i) => (
              <button
                key={i}
                type="button"
                onClick={() => setPage(i)}
                className={`rounded-full ${i === page ? 'h-2 w-6 bg-[#CDB17E]' : 'h-2 w-2 bg-[#D4D4D4]'}`}
                aria-label={`Page ${i + 1}`}
              />
            ))}
          </div>
        </>
      )}
    </div>
  )
}

function PackageOfferPrice({
  price,
  originalPrice = '',
  discountBadge = '',
  priceClassName = 'text-[20px] font-medium text-[#591902] sm:text-[22px]',
}) {
  if (!price) return null

  return (
    <div className="flex shrink-0 flex-wrap items-center justify-end gap-x-2 gap-y-1 pt-1">
      {discountBadge ? (
        <span className="package-offer-badge inline-flex items-center gap-1 rounded-full bg-gradient-to-r from-[#CDB17E] via-[#E2C89A] to-[#D4BA8E] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.06em] text-[#591902] shadow-[0_2px_12px_rgba(205,177,126,0.55)] sm:text-[11px]">
          <span aria-hidden="true">★</span>
          {discountBadge}
        </span>
      ) : null}
      <span className={priceClassName}>{price}</span>
      {originalPrice ? (
        <span className="text-[12px] text-[#8A847E] line-through sm:text-[13px]">{originalPrice}</span>
      ) : null}
    </div>
  )
}

function ProductImageLayout({
  title,
  price,
  originalPrice = '',
  discountBadge = '',
  intro,
  customDetailsContent,
  beforePriceContent,
  customPriceContent,
  customContent,
  accordionSections,
  mainImage,
  sideImages,
  imageMetaByUrl,
  quantity,
  onDecrement,
  onIncrement,
  promptContent,
  addToCartDisabled,
  addToCartButtonLabel,
  addToCartMessage,
  relatedProducts,
  onAddToCart,
  ctaButtonText,
  testimonials,
  desktopSectionTop,
  hideHeaderPrice,
  consultationOnly = false,
  consultationPath = BOOK_CONSULTATION_PATH,
}) {
  const normalizedMainImage = mainImage ?? null
  const initialDisplayImage = mainImage ?? sideImages[0]
  const [selectedOverride, setSelectedOverride] = useState(null)
  const [trackedMainImage, setTrackedMainImage] = useState(normalizedMainImage)
  const [isCartOptionsOpen, setIsCartOptionsOpen] = useState(false)
  const [isLightboxOpen, setIsLightboxOpen] = useState(false)

  const scrollToProductOptions = useCallback(() => {
    const options = document.getElementById('product-options')
    if (options) {
      options.scrollIntoView({ behavior: 'smooth', block: 'start' })
      return
    }
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }, [])

  if (trackedMainImage !== normalizedMainImage) {
    setTrackedMainImage(normalizedMainImage)
    setSelectedOverride(null)
  }

  const galleryUrls = [mainImage, ...sideImages].filter(Boolean)
  const activeImage =
    selectedOverride && galleryUrls.includes(selectedOverride)
      ? selectedOverride
      : initialDisplayImage
  const activeImageMeta = activeImage ? imageMetaByUrl?.[activeImage] : null

  useEffect(() => {
    setIsLightboxOpen(false)
  }, [activeImage])

  useEffect(() => {
    const urls = [mainImage, ...sideImages].filter(Boolean)
    preloadImages(urls)
  }, [mainImage, sideImages])

  return (
    <main className="min-h-screen bg-[#F2F2F2] text-[#E8D2B1]">
      <NavHeader />
      <section className="relative pb-16 pt-8 md:pt-14.5">
        <div
          className="relative mx-auto flex flex-col border-t-2 border-[#2D2D2D] md:flex-row md:items-start md:justify-between"
          style={{
            maxWidth: '1540px',
            gap: 'clamp(1.5rem, 2.2vw, 2rem)',
            paddingLeft: 'clamp(20px, 5.5vw, 100px)',
            paddingRight: 'clamp(20px, 5.5vw, 100px)',
          }}
        >
          <div
            className="top-15 md:sticky md:self-start md:shrink-0"
            style={{ top: desktopSectionTop }}
          >
            <div className="flex w-full flex-row items-start gap-2 pt-8 md:gap-4 md:pt-0">
              {/* Main Image */}
              <div
                className="order-2 min-w-0 flex-1 mx-auto md:order-2 md:max-w-[clamp(17.5rem,38vw,37.5rem)]"
              >
                <button
                  type="button"
                  onClick={() => activeImage && setIsLightboxOpen(true)}
                  className={`relative block w-full cursor-zoom-in overflow-hidden ${GALLERY_VIEWPORT_HEIGHT_CLASS}`}
                  aria-label={`View full size image for ${title}`}
                >
                  <BrandedImage
                    src={activeImage}
                    alt={title}
                    eager
                    cropWatermark
                    className="h-full w-full border-l-2 border-r-2 border-b-2 border-[#727355] bg-white"
                    imgClassName="object-cover object-center"
                  />

                  {activeImageMeta?.heading || activeImageMeta?.text ? (
                    <div className="pointer-events-none absolute bottom-3 right-3 z-10 max-w-[70%] rounded-full bg-[#591902] px-3.5 py-1.5 text-white shadow-sm">
                      <p className="truncate text-[11px] font-semibold leading-none tracking-wide">
                        {activeImageMeta?.heading || activeImageMeta?.text}
                      </p>
                    </div>
                  ) : null}
                </button>
                <PackageImageDisclaimer className="mt-1.5 text-center" />
              </div>

              {/* Side Images */}
              {sideImages.length > 0 ? (
                <div
                  className={`order-1 flex w-[4.25rem] min-w-[4.25rem] shrink-0 flex-col items-stretch gap-2 overflow-y-auto pb-0 pt-0 md:order-1 md:w-[clamp(4rem,5vw,5rem)] md:min-w-[clamp(4rem,5vw,5rem)] md:gap-2 md:pt-2 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden ${SIDE_IMAGES_SCROLL_CLASS}`}
                  data-lenis-prevent
                >
                  {sideImages.map((image, index) => (
                    <button
                      type="button"
                      key={`${image}-${index}`}
                      onClick={() => setSelectedOverride(image)}
                      className={`${SIDE_THUMB_BUTTON_CLASS} ${
                        activeImage === image ? 'opacity-100' : 'opacity-40'
                      }`}
                      aria-label={`Show ${title} preview ${index + 1}`}
                      aria-pressed={activeImage === image}
                    >
                      <BrandedImage
                        src={image}
                        alt={`${title} preview ${index + 1}`}
                        cropWatermark
                        className="h-full w-full rounded-[14px]"
                        imgClassName="rounded-[14px] object-cover"
                      />
                    </button>
                  ))}
                </div>
              ) : null}
            </div>
          </div>

          <div
            className="mx-auto w-full min-w-0 flex-1 lg:mx-0"
            style={{
              maxWidth: 'clamp(20rem, 42vw, 40.75rem)',
              paddingLeft: 'clamp(0rem, 1.5vw, 2.25rem)',
            }}
          >
            {customDetailsContent ? (
              <div id="product-options" className="mt-5 scroll-mt-24 md:pr-3">
                {customDetailsContent}
              </div>
            ) : (
              <>
                <div className="mt-5 flex items-start justify-between gap-4 md:pr-3">
                  <h1
                    className="min-w-0 text-[28px] leading-[0.95] text-[#591902] sm:text-[34px] md:text-[36px]"
                    style={{ fontFamily: "'Malgin', serif" }}
                  >
                    {title}
                  </h1>
                  {!hideHeaderPrice ? (
                    <PackageOfferPrice
                      price={price}
                      originalPrice={originalPrice}
                      discountBadge={discountBadge}
                    />
                  ) : null}
                </div>

                {intro ? (
                  <p className="mt-4 max-w-[540px] text-[14px] leading-[1.6] text-[#2D2D2D] opacity-80">
                    {intro}
                  </p>
                ) : null}

                {beforePriceContent ? (
                  <div className={intro ? 'mt-6' : 'mt-4'}>{beforePriceContent}</div>
                ) : null}

                {customPriceContent ? customPriceContent : null}

                {!consultationOnly ? (
                  <QuantityControl
                    quantity={quantity}
                    onDecrement={onDecrement}
                    onIncrement={onIncrement}
                  />
                ) : null}

                {promptContent && <div className="mt-5">{promptContent}</div>}

                {consultationOnly ? (
                  <ConsultationLinkButton
                    label={ctaButtonText}
                    consultationPath={consultationPath}
                    className={promptContent ? 'mt-4' : 'mt-5'}
                  />
                ) : (
                  <button
                    type="button"
                    disabled={addToCartDisabled}
                    onClick={onAddToCart}
                    className={`group ${promptContent ? 'mt-4' : 'mt-5'} flex w-full items-center justify-between rounded-full pl-6 pr-1.5 py-1.5 text-[13px] font-medium transition-colors ${
                      addToCartDisabled
                        ? 'cursor-not-allowed bg-[#CDB17E] text-[#8A847E]'
                        : 'bg-[#D4BA8E] text-white hover:bg-[#C6AB7F]'
                    }`}
                  >
                    <span className="mr-5">{addToCartButtonLabel}</span>
                    <span
                      className={`flex h-9 w-9 items-center justify-center rounded-full shadow-sm ${
                        addToCartDisabled ? 'bg-[#E2DEDA] text-[#9B958E]' : 'bg-white text-[#D4BA8E]'
                      }`}
                    >
                      <svg
                        className={`h-[24px] w-[24px] transition-transform duration-300 ease-out ${
                          addToCartDisabled ? '' : 'group-hover:rotate-none'
                        }`}
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                        strokeWidth="2.5"
                      >
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 7v10M7 12h10" />
                      </svg>
                    </span>
                  </button>
                )}

                {!consultationOnly && addToCartMessage ? (
                  <p className="mt-3 text-[12px] leading-[1.5] text-[#591902] opacity-70">
                    {addToCartMessage}
                  </p>
                ) : null}

                {customContent ? (
                  <div className="mt-8 border-t border-[#36402280] pt-5">{customContent}</div>
                ) : null}

                <div className="mt-8">
                  {accordionSections.map((section, index) => (
                    <AccordionSection
                      key={section.title}
                      title={section.title}
                      body={section.body}
                      defaultOpen={index === 0}
                    />
                  ))}
                </div>
              </>
            )}
          </div>
        </div>
      </section>

      <section className="pb-16">
        <div className="mx-auto md:w-full max-w-[1540px]">
          {relatedProducts.length > 0 ? (
            <RelatedProductsCarousel products={relatedProducts} hidePrice={consultationOnly} />
          ) : null}

          <div className="mt-8 bg-[#E7E0DA] py-6 px-6 sm:px-[40px] lg:px-[60px]">
            <div className="grid grid-cols-2 gap-5 sm:grid-cols-3 md:grid-cols-5">
              {TRUST_ITEMS.map(({ label, Icon }) => (
                <div key={label} className="flex flex-col items-center text-center text-[#3A312A]">
                  <Icon />
                  <p className="mt-3 text-[16px] font-medium">{label}</p>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-[#591902] px-6 py-10 text-center text-white lg:py-12">
            <h2
              className="text-[24px] font-semibold leading-tight md:text-[36px]"
              style={{ fontFamily: "'Malgin', serif" }}
            >
              Still confused, excited, or somewhere in between?
            </h2>
            <p className="mx-auto mt-3 max-w-[560px] text-[16px] leading-[1.6] text-white/70">
              Drop your details and we&apos;ll get in touch. You are just one call away from turning
              the confusion into a clear, sorted plan.
            </p>
            <Link
              to="/book-consultation"
              className="mx-auto group mt-8 flex w-fit items-center rounded-full bg-[#D4BA8E] pl-6 pr-1.5 py-1.5 transition-colors hover:bg-[#C6AB7F]"
            >
              <span className="mr-5 text-[15px] font-medium text-white">{ctaButtonText}</span>
              <div className="flex h-9 w-9 items-center justify-center rounded-full bg-white shadow-sm">
                <svg
                  className="h-[20px] w-[20px] text-[#D4BA8E] transition-transform duration-300 ease-out group-hover:rotate-45 group-hover:text-[#C6AB7F]"
                  viewBox="0 0 20 20"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    d="M5.82812 5.83398H14.1615M14.1615 5.83398V14.1673M14.1615 5.83398L5.82812 14.1673"
                    stroke="currentColor"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </div>
            </Link>
          </div>

          <div className="mt-10 lg:mt-14 px-6 sm:px-[50px] lg:px-[100px]">
            <p
              className="text-[22px] font-semibold text-[#2D2D2D] md:text-[32px]"
              style={{ fontFamily: "'Malgin', serif" }}
            >
              Moments They Loved
            </p>
            <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-3">
              {testimonials.length > 0 ? (
                testimonials.map((item, index) => (
                  <article
                    key={`${item.id ?? item.name}-${index}`}
                    className="border border-[#D8CEC2] bg-white p-3 rounded-xl shadow-[0_6px_18px_rgba(0,0,0,0.06)]"
                  >
                    <div className="flex items-center justify-between gap-3 pb-2">
                      <p className="text-[15px] md:text-[27px] font-semibold text-[#2D2D2D]">
                        {item.name}
                      </p>
                      <p className="text-[12px] md:text-[16px] text-[#2D2D2D]">{item.date}</p>
                    </div>
                    <img
                      src={item.image || mainImage}
                      alt={`${item.name} event`}
                      className="mt-3 h-[324px] w-full object-cover"
                    />
                    <p className="mt-3 text-[12px] md:text-[16px] leading-[1.6] text-[#2D2D2D]">
                      {item.quote}
                    </p>
                  </article>
                ))
              ) : (
                <div className="rounded-[18px] border border-[#D8CEC2] bg-white px-6 py-8 text-[#2D2D2D] md:col-span-3">
                  <p className="text-[14px] leading-[1.6]">
                    No reviews are available for this package yet.
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>
      </section>

      <section className="pb-16">
        <div className="fixed bottom-0 left-0 z-50 w-full bg-[#591902] px-4 text-white sm:px-6 md:h-[70px] md:px-[50px] lg:px-[100px]">
          <div className="mx-auto flex min-h-[60px] max-w-[1400px] items-center justify-between gap-3 py-2 md:py-4">
            {/* Left */}
            <div className="flex min-w-0 flex-1 items-start gap-2 md:items-center md:gap-3">
              <h2 className="min-w-0 text-[11px] font-semibold leading-snug sm:text-xs md:text-sm lg:text-base">
                {title}
              </h2>
              {!consultationOnly ? (
                <>
                  <span className="hidden shrink-0 md:inline">–</span>
                  <span className="shrink-0 text-xs font-bold sm:text-sm md:text-base text-[#D4BA8E]">
                    <span className="inline-flex flex-wrap items-center gap-2">
                      {discountBadge ? (
                        <span className="package-offer-badge inline-flex items-center gap-1 rounded-full bg-gradient-to-r from-[#CDB17E] to-[#D4BA8E] px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-[#591902]">
                          <span aria-hidden="true">★</span>
                          {discountBadge}
                        </span>
                      ) : null}
                      <span>{price}</span>
                      {originalPrice ? (
                        <span className="font-normal text-white/60 line-through">{originalPrice}</span>
                      ) : null}
                    </span>
                  </span>
                </>
              ) : null}
            </div>

            {/* Right */}
            <div className="flex shrink-0 items-center gap-2 sm:gap-4 md:gap-6">
              {!consultationOnly ? (
                <button
                  type="button"
                  className="text-xs underline sm:text-sm md:text-base"
                  onClick={() => setIsCartOptionsOpen(true)}
                >
                  View Options
                </button>
              ) : null}

              {consultationOnly ? (
                <Link
                  to={consultationPath}
                  className="group flex items-center rounded-full bg-[#D4BA8E] py-1.5 pl-3 pr-1 text-[12px] font-medium text-white transition-colors hover:bg-[#C6AB7F] sm:pl-4 sm:pr-1.5 sm:text-[13px] md:pl-6"
                >
                  <span className="mr-2 sm:mr-3 md:mr-5">{ctaButtonText}</span>
                  <span className="flex h-7 w-7 items-center justify-center rounded-full bg-white text-[#D4BA8E] shadow-sm sm:h-8 sm:w-8">
                    <svg
                      className="h-[20px] w-[20px] transition-transform duration-300 ease-out group-hover:rotate-45"
                      viewBox="0 0 20 20"
                      fill="none"
                      xmlns="http://www.w3.org/2000/svg"
                    >
                      <path
                        d="M5.82812 5.83398H14.1615M14.1615 5.83398V14.1673M14.1615 5.83398L5.82812 14.1673"
                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                  </span>
                </Link>
              ) : (
                <button
                  className={`group flex items-center rounded-full py-1.5 pl-3 pr-1 text-[12px] font-medium transition-colors sm:pl-4 sm:pr-1.5 sm:text-[13px] md:pl-6 ${
                    addToCartDisabled
                      ? 'cursor-not-allowed bg-[#CDB17E] text-[#8A847E]'
                      : 'bg-[#D4BA8E] text-white hover:bg-[#C6AB7F]'
                  }`}
                  disabled={addToCartDisabled}
                  type="button"
                  onClick={onAddToCart}
                >
                  <span className="mr-2 sm:mr-3 md:mr-5">{addToCartButtonLabel}</span>
                  <span
                    className={`flex h-7 w-7 items-center justify-center rounded-full shadow-sm sm:h-8 sm:w-8 ${
                      addToCartDisabled ? 'bg-[#E2DEDA] text-[#9B958E]' : 'bg-white text-[#D4BA8E]'
                    }`}
                  >
                    <svg
                      className={`h-[24px] w-[24px] transition-transform duration-300 ease-out ${
                        addToCartDisabled ? '' : 'group-hover:rotate-none'
                      }`}
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                      strokeWidth="2.5"
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" d="M12 7v10M7 12h10" />
                    </svg>
                  </span>
                </button>
              )}
            </div>
          </div>
        </div>
      </section>

      <CartViewOptionsSheet
        open={isCartOptionsOpen}
        onClose={() => setIsCartOptionsOpen(false)}
        onBrowseOptions={scrollToProductOptions}
      />

      <Footer />
      <PackageImageLightbox
        open={isLightboxOpen}
        image={activeImage}
        title={title}
        onClose={() => setIsLightboxOpen(false)}
      />
    </main>
  )
}
